INSERT INTO shop_book VALUES(1,'Астра','1231425','2026-06-08','2026-06-21 12:15:09.055472',6,230,'Українська',0,1,'«Астра» — це захоплива історія життя Віктора Варецького, розказана ним самим. Історія пошуку відповідей на запитання, які краще не ставити. Пошук правди, на шляху до якої губиш усіх, кого любив. І розумієш: усе вигадка, все ілюзія. Мандрівка дорогою, що веде серце темряви, в основу світобудови.');
INSERT INTO shop_book VALUES(2,'Понтиїзм','86548646','2025-11-04','2026-06-21 12:18:12.328033',12,430,'Українська',0,2,'«Понтиїзм» – це історії про черговий кінець світу у країні, життя в якій уже давно є безкінечним апокаліпсисом. Оповіді про прірву, що ховається за кожним полотном – хоч асфальтом, хоч картиною. Казки про любов, зраду, кров, ненависть, м’ясо і шлюб. Хроніки віртуальної війни під проводом віртуальних генералів невіртуальної держави. Проповіді жорстокого вірування в понти, яким поклоняється більшість країни.');
INSERT INTO shop_book VALUES(3,'Миротворець','486756','2026-06-21','2026-06-21 12:26:22.169641',3,440,'Українська',0,3,'Нова книжка молодого українського письменника складається з двох повістей та оповідань. Перед нами постає зовсім несподіваний і трохи загадковий Любко Дереш... "Миротворець" - дивні історії, сумні та загадкові, леймотивом яких звучить філософська думка: "ГЕНІЇ ТА ГЕРОЇ ЗАВЖДИ САМОТНІ..."');
INSERT INTO shop_book VALUES(4,'Пісні про любов та вічність','242587487','2026-06-10','2026-06-21 12:27:04.785981',5,330,'Українська',0,3,unistr('Любко Дереш, як завжди, інтригує, ставить у своїх текстах запитання, на які дає парадоксальні відповіді. За які принципи треба триматись у цьому житті? І чи потрібні вони взагалі? У чому справжня цінність людини? До чого призводять пошуки глибинних смислів буття?\u000a\u000aЛюбко Дереш пропонує шукати свої власні відповіді на питання, що ставлять пісні про любов і вічність.'));
INSERT INTO shop_book VALUES(5,'Гімн демократичної молоді','3456789','2025-09-01','2026-06-21 12:27:54.538917',9,350,'Українскька',0,1,unistr('Герої збірки оповідань Сергія Жадана постійно шукають спосіб швидко заробити й вибратися з безгрошів’я на початку двотисячних. Вони відкривають гей-клуби, беруться за сумнівні підробітки, намагаються провернути дивні схеми й постійно опиняються в неприємностях. В оповіданнях поєднуються нові авантюри, випадкові знайомства, алкоголь, хаотичні поїздки й люди, які вперто вірять, що наступна геніальна ідея точно спрацює.\u000a\u000aЗа цими абсурдними пригодами поступово відкривається життя покоління, яке намагається знайти себе в реальності, де старі правила вже не працюють, а нові ще ніхто не вигадав. Книга сподобається шанувальникам сучасної української прози, сатиричних історій та чорного гумору.'));
INSERT INTO shop_book VALUES(6,'Життя Марії','565466g','2025-11-09','2026-06-21 13:01:49.792901',1,280,'Українська',0,2,unistr('Книга "Життя Марії" – Роздуми про людяність та порозуміння\u000aСергій Жадан є видатним українським поетом та прозаїком, який приніс значний внесок у сучасну українську літературу. Його твори, включаючи збірку "Життя Марії", вразливо й потужно спілкуються зі своїми читачами, переплітаючи важливі мотиви та думки.'));
INSERT INTO shop_book VALUES(7,'PSI*','64689859','2025-05-05','2026-06-21 13:02:46.144249',11,189,'Українська',0,1,'«PSI*» — це дебютна поетична збірка харківської поетеси та режисерки Настасьї Мілевської, що вийшла у 2014 році. Її творчість відзначається емоційністю, інтимною лірикою та часто балансує на межі літератури й моноспектаклю.');
INSERT INTO shop_book VALUES(8,'Рух життя, або Динамо','6543865462','2026-03-09','2026-06-21 13:03:44.483424',13,629.990000000000009,'Українська',0,3,unistr('Лесь Подерв’янський (нар. 1952 р.) — скандально відомий український письменник і художник. Його епатажні п’єси, що були спочатку записані на аудіокасетах, принесли йому широку популярність. Тепер з його творами можна ознайомитися на сторінках книжок. Читаючи Подерв’янського, ви відкриєте для себе, що його герої, на жаль, не такі вже нереальні, як це може здатися на перший погляд, а тонка іронія та гумор автора дозволять вам ще і ще раз посміхнутися над трагікомізмом нашого життя.\u000a'));
INSERT INTO shop_book VALUES(9,'Герой нашого часу','7684763','2025-06-18','2026-06-21 13:04:27.402431',5,339,'Українська',0,2,unistr('Лесь Подерв’янський (нар. 1952 р.) — скандально відомий український письменник і художник. Його епатажні п’єси, що були спочатку записані на аудіокасетах, принесли йому широку популярність. Тепер з його творами можна ознайомитися на сторінках книжок. Читаючи Подерв’янського, ви відкриєте для себе, що його герої, на жаль, не такі вже нереальні, як це може здатися на перший погляд, а тонка іронія та гумор автора дозволять вам ще і ще раз посміхнутися над трагікомізмом нашого життя.\u000a'));
INSERT INTO shop_book VALUES(10,'Павлік Морозов','7875468375','2026-06-21','2026-06-21 13:05:07.591016',10,361.9000000000000342,'Українська',0,1,'Лесь Подерв’янський (нар. 1952 р.) — скандально відомий український письменник і художник. Його епатажні п’єси, що були спочатку записані на аудіокасетах, принесли йому широку популярність. Тепер з його творами можна ознайомитися на сторінках книжок. Читаючи Подерв’янського, ви відкриєте для себе, що його герої, на жаль, не такі вже нереальні, як це може здатися на перший погляд, а тонка іронія та гумор автора дозволять вам ще і ще раз посміхнутися над трагікомізмом нашого життя.');
